const rows = $input.all();

const mapMaquinas = {};
const mapReferencias = {};

for (const item of rows) {
  const row = item.json;
  if (row.tipo === 'maquina') {
    if (row.clave) mapMaquinas[row.clave] = row.id;
  } else if (row.tipo === 'referencia') {
    if (row.clave) mapReferencias[row.clave] = row.id;
  }
}

$getWorkflowStaticData('global').mapeoMaquinas = mapMaquinas;
$getWorkflowStaticData('global').mapeoReferencias = mapReferencias;

return [{ json: { mapeos_cargados: true } }];

const loteItems = $input.all().map(item => item.json);
const mapMaquinas = $getWorkflowStaticData('global').mapeoMaquinas || {};
const mapReferencias = $getWorkflowStaticData('global').mapeoReferencias || {};

// ----- ACUMULAR IDs PROCESADOS -----
const staticData = $getWorkflowStaticData('global');
if (!staticData.programacionesProcesadas) staticData.programacionesProcesadas = [];
const ids = loteItems
  .map(item => String(item.ID_Programacion || '').trim())
  .filter(id => id);
staticData.programacionesProcesadas.push(...ids);
// -----------------------------------

const escape = (v) => String(v).replace(/'/g, "''");
const formatTimestamp = (fechaStr) => {
  if (!fechaStr) return 'NULL';
  const normalizada = fechaStr.replace(/[-_.]/g, '/');
  const partes = normalizada.split('/');
  if (partes.length !== 3) return 'NULL';
  const [d, m, a] = partes;
  return `'${a}-${m.padStart(2, '0')}-${d.padStart(2, '0')} 00:00:00'`;
};
const parseNumber = (val) => {
  if (!val) return 0;
  const num = parseFloat(String(val).replace(',', '.'));
  return isNaN(num) ? 0 : num;
};

const values = loteItems.map(item => {
  const id = escape(String(item.ID_Programacion || '').trim());
  const kilos = parseNumber(item.CantidadKilos_Programacion);
  const horas = parseNumber(item.DuracionEstimada_Programacion);

  const ot = item.IDOrdenTrabajo_Programacion ? `'${escape(item.IDOrdenTrabajo_Programacion)}'` : 'NULL';
  const cliente = item.IDCliente_Programacion ? `'${escape(item.IDCliente_Programacion)}'` : 'NULL';
  const refLegacy = item.IDReferencia_Programacion ? `'${escape(item.IDReferencia_Programacion)}'` : 'NULL';
  const proceso = item.Proceso_Programacion ? `'${escape(item.Proceso_Programacion)}'` : 'NULL';
  const estado = item.Estado_Programacion ? `'${escape(item.Estado_Programacion)}'` : 'NULL';

  const fechaInicio = formatTimestamp(item.Fecha_Programacion);
  const fechaEstimada = formatTimestamp(item.FechaEntrega_Programacion);

  const rawIdMaquina = mapMaquinas[item.Maquina_Programacion];
  const idMaquina = rawIdMaquina ? `'${escape(rawIdMaquina)}'` : 'NULL';

  const rawIdReferencia = mapReferencias[item.IDReferencia_Programacion];
  const idReferencia = rawIdReferencia ? `'${escape(rawIdReferencia)}'` : 'NULL';

  // kilos producidos = kilos programados si el estado es "Terminada", sino 0
  const terminada = (item.Estado_Programacion || '').toString().toLowerCase() === 'terminada';
  const kilosProducidos = terminada ? kilos : 0;

  // Se añade el campo kilos_producidos al final de la tupla (antes del cierre)
  return `('${id}', ${kilos}, ${ot}, ${cliente}, ${estado}, ${proceso}, ${fechaInicio}, ${fechaEstimada}, NULL, ${ot}, ${cliente}, ${refLegacy}, ${idReferencia}, ${idMaquina}, 0, NULL, NULL, ${horas}, ${kilosProducidos})`;
}).join(', ');

const sql = `INSERT INTO public.programaciones 
(legacy_programacion_id, kilos, ot, cliente, estado, proceso, fecha_inicio, fecha_estimada, fecha_real, legacy_ot_id, legacy_cliente_id, legacy_referencia_id, id_referencia, id_maquina, orden_secuencia, fecha_inicio_estimada, fecha_fin_estimada, horas_estimadas_totales, kilos_producidos)
VALUES ${values}
ON CONFLICT (legacy_programacion_id) DO UPDATE SET
  kilos = EXCLUDED.kilos,
  ot = EXCLUDED.ot,
  cliente = EXCLUDED.cliente,
  estado = EXCLUDED.estado,
  proceso = EXCLUDED.proceso,
  fecha_inicio = EXCLUDED.fecha_inicio,
  fecha_estimada = EXCLUDED.fecha_estimada,
  fecha_real = EXCLUDED.fecha_real,
  legacy_ot_id = EXCLUDED.legacy_ot_id,
  legacy_cliente_id = EXCLUDED.legacy_cliente_id,
  legacy_referencia_id = EXCLUDED.legacy_referencia_id,
  id_referencia = EXCLUDED.id_referencia,
  id_maquina = EXCLUDED.id_maquina,
  orden_secuencia = EXCLUDED.orden_secuencia,
  fecha_inicio_estimada = EXCLUDED.fecha_inicio_estimada,
  fecha_fin_estimada = EXCLUDED.fecha_fin_estimada,
  horas_estimadas_totales = EXCLUDED.horas_estimadas_totales,
  kilos_producidos = EXCLUDED.kilos_producidos;`;

return [{ json: { sql } }];

// La eficiencia ya fue guardada en static data por el nodo "Guardar eficiencia en static"
const mapaKgHora = $getWorkflowStaticData('global').mapeoMaquinasKgHora || {};

// Programaciones desde la consulta SQL
const programaciones = $input.all()
  .map(item => item.json)
  .filter(obj => obj['Fecha de programación (Automatico)'] !== undefined);

const grupos = {};
for (const prog of programaciones) {
  const nombreMaquina = (prog['Maquina (Automatico)'] || '').trim();
  if (!grupos[nombreMaquina]) grupos[nombreMaquina] = [];
  grupos[nombreMaquina].push(prog);
}

const resultados = [];
const ahora = new Date();

// ========== FUNCIÓN PARA FORMATEAR EN ISO 8601 (solo fecha) ==========
const fmtFecha = (d) => {
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

// Función para obtener solo la fecha de un timestamp (string o Date) en YYYY-MM-DD
const aFecha = (val) => {
  if (!val) return '';
  const d = new Date(val);
  if (isNaN(d.getTime())) return '';
  return fmtFecha(d);
};

for (const [nombreMaquina, tareas] of Object.entries(grupos)) {
  tareas.sort((a, b) => 
    new Date(a['Inicio (Automatico)'] || a['Fecha de programación (Automatico)']) - 
    new Date(b['Inicio (Automatico)'] || b['Fecha de programación (Automatico)'])
  );
  const kgHora = mapaKgHora[nombreMaquina.toLowerCase()] || 100;
  let fechaOcupada = new Date(ahora);

  // Determinar si es área de extrusión (para combinar turnos B y C)
  const esExtrusion = nombreMaquina.toLowerCase().includes('extrusora');

  for (const prog of tareas) {
    const kilosHechos = parseFloat(prog['Kilos hechos (Automatico)']) || 0;
    const kilosProgramados = parseFloat(prog['Kilos programados (Automatico)']) || 0;
    const kilosPedidos = parseFloat(prog['Kilos pedidos (Automatico)']) || 0;

    const inicioStr = prog['Inicio (Automatico)'] || prog['Fecha de programación (Automatico)'];
    const finStr = prog['Finalizacion (Automatico)'] || prog['Fin Planeado (Automatico)'] || prog['Fecha de programación (Automatico)'];
    if (!inicioStr || !finStr) continue;

    const inicioOriginal = new Date(inicioStr);
    const finOriginal = new Date(finStr);
    if (isNaN(inicioOriginal.getTime())) continue;

    const fechaProgramacion = new Date(prog['Fecha de programación (Automatico)']);
    const kilosRestantes = Math.max(kilosProgramados - kilosHechos, 0);
    const horasNecesarias = kgHora > 0 ? kilosProgramados / kgHora : 0;
    const turnos = Math.ceil(horasNecesarias / 8);
    const fechaSugerida = new Date(fechaOcupada);
    const finSugerido = new Date(fechaSugerida.getTime() + horasNecesarias * 60 * 60 * 1000);
    fechaOcupada = finSugerido;

    const ultimaProduccion = aFecha(prog['Ultima Producción (automático)']);

    // ----- NUEVOS CAMPOS DE TURNO (con ajuste para extrusión) -----
    let kilosTurnoA = parseFloat(prog['Kilos Turno A']) || 0;
    let kilosTurnoB = parseFloat(prog['Kilos Turno B']) || 0;
    let kilosTurnoC = parseFloat(prog['Kilos Turno C']) || 0;

    if (esExtrusion) {
      // En extrusión solo hay dos turnos: A y B. El Turno C (Turno 3) se suma al Turno B.
      kilosTurnoB += kilosTurnoC;
      kilosTurnoC = 0;
    }

    resultados.push({
      json: {
        'Fecha de programación (Automatico)': fmtFecha(fechaProgramacion),
        'OT (Automatico)': prog['OT (Automatico)'] || '',
        'Cliente (Automatico)': prog['Cliente (Automatico)'] || '',
        'Maquina (Automatico)': nombreMaquina,
        'Referencia (automatico)': prog['Referencia (automatico)'] || '',
        'Kilos hechos (Automatico)': kilosHechos,
        'Tiempo de producción real (Automatico)': parseFloat(prog['Tiempo de producción real (Automatico)']) || 0,
        'Kilos programados (Automatico)': kilosProgramados,
        'Kilos restantes (Automatico)': kilosRestantes,
        'Kilos pedidos (Automatico)': kilosPedidos,
        'Cuantos turnos se usaran (Automatico)': turnos,
        'Fecha sugerido de Inicio (Automatico)': fmtFecha(fechaSugerida),
        'Tiempo estimado (Automatico)': parseFloat(horasNecesarias.toFixed(2)),
        'Inicio (Automatico)': fmtFecha(inicioOriginal),
        'Finalizacion (Automatico)': fmtFecha(finOriginal),
        'Estado (Automatico)': prog['Estado (Automatico)'] || 'En Proceso',
        'Ultima Producción (automático)': ultimaProduccion,
        'Observaciones finales': prog['Observaciones finales'] || '',
        'Kilos Turno A': kilosTurnoA,
        'Kilos Turno B': kilosTurnoB,
        'Kilos Turno C': kilosTurnoC
      }
    });
  }
}

return resultados;

const idsProcesados = $getWorkflowStaticData('global').programacionesProcesadas || [];

if (idsProcesados.length === 0) {
  // Si no hay IDs, no generamos DELETE para evitar borrar todo
  return [{ json: { sql: null } }];
}

const lista = idsProcesados.map(id => `'${String(id).replace(/'/g, "''")}'`).join(', ');
const sql = `DELETE FROM public.programaciones WHERE legacy_programacion_id NOT IN (${lista})`;

return [{ json: { sql } }];

const eficiencia = $input.all().map(i => i.json);
const mapaKgHora = {};
eficiencia.forEach(m => {
  if (m.nombre) mapaKgHora[m.nombre.trim().toLowerCase()] = parseFloat(m.kg_hora) || 100;
});
$getWorkflowStaticData('global').mapeoMaquinasKgHora = mapaKgHora;
return eficiencia;  // pasamos los mismos datos hacia el siguiente nodo
